import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>
#include <torch/extension.h>

__global__ void fused_bias_gelu_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int rows,
    int cols
) {
    // Shared memory layout:
    // [0 ... cols-1]: row data (values)
    // [cols ... cols+blockDim.x-1]: reduction buffer
    extern __shared__ float shared_mem[];
    float* row_data = shared_mem;
    float* sdata = &row_data[cols];

    int tid = threadIdx.x;
    int row_idx = blockIdx.x;

    if (row_idx >= rows) return;

    int row_offset = row_idx * cols;

    // 1. Load, Add Bias, GELU, Find Max
    float local_max = -INFINITY;
    const float SQRT_2_INV = 0.70710678f;

    for (int i = tid; i < cols; i += blockDim.x) {
        float val = input[row_offset + i] + bias[i];

        // GELU Exact: 0.5 * x * (1 + erf(x / sqrt(2)))
        val = 0.5f * val * (1.0f + erff(val * SQRT_2_INV));

        row_data[i] = val;
        if (val > local_max) local_max = val;
    }

    // Block Reduce Max
    sdata[tid] = local_max;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (sdata[tid + s] > sdata[tid]) sdata[tid] = sdata[tid + s];
        }
        __syncthreads();
    }
    float row_max_val = sdata[0];

    // 2. Compute Exp and Sum
    float local_sum = 0.0f;
    for (int i = tid; i < cols; i += blockDim.x) {
        float val = row_data[i];
        val = expf(val - row_max_val);
        row_data[i] = val;
        local_sum += val;
    }

    // Block Reduce Sum
    sdata[tid] = local_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    float row_sum_val = sdata[0];

    // 3. Normalize and Write
    float inv_sum = 1.0f / row_sum_val;

    for (int i = tid; i < cols; i += blockDim.x) {
        output[row_offset + i] = row_data[i] * inv_sum;
    }
}

torch::Tensor fused_bias_gelu_softmax_hip(torch::Tensor input, torch::Tensor bias) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);

    const int block_size = 1024;
    const int grid_size = rows;

    // Shared memory: cols floats + block_size floats
    int shared_mem_size = (cols + block_size) * sizeof(float);

    fused_bias_gelu_softmax_kernel<<<grid_size, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols
    );

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    functions=["fused_bias_gelu_softmax_hip"],
    verbose=True,
    extra_cflags=['-O3'],
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.fused_ops = fused_ops

    def forward(self, x):
        x_mm = torch.mm(x, self.linear.weight.t())
        return self.fused_ops.fused_bias_gelu_softmax_hip(x_mm, self.linear.bias)

