cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>
#include <cstdint>

__global__ void fused_bias_div_gelu_vec_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float divisor,
    int cols,
    int total_vecs
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_vecs) {
        // Vectorized load/store
        const float4* in_vec = reinterpret_cast<const float4*>(input);
        const float4* b_vec = reinterpret_cast<const float4*>(bias);
        float4* out_vec = reinterpret_cast<float4*>(output);

        float4 v = in_vec[idx];

        // Bias index calculation
        int vec_cols = cols >> 2; // cols / 4
        int col_idx = idx % vec_cols;
        float4 b = b_vec[col_idx];

        float inv_div = 1.0f / divisor;
        float k = 0.707106781f; // 1/sqrt(2)

        // Computation for each component
        // x = (x + bias) / divisor
        // out = 0.5 * x * (1 + erf(x/sqrt(2)))

        v.x = (v.x + b.x) * inv_div;
        v.x = 0.5f * v.x * (1.0f + erff(v.x * k));

        v.y = (v.y + b.y) * inv_div;
        v.y = 0.5f * v.y * (1.0f + erff(v.y * k));

        v.z = (v.z + b.z) * inv_div;
        v.z = 0.5f * v.z * (1.0f + erff(v.z * k));

        v.w = (v.w + b.w) * inv_div;
        v.w = 0.5f * v.w * (1.0f + erff(v.w * k));

        out_vec[idx] = v;
    }
}

__global__ void fused_bias_div_gelu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float divisor,
    int cols,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int col = idx % cols;
        float val = input[idx];
        float b = bias[col];

        val = (val + b) / divisor;

        float k = 0.707106781f;
        val = 0.5f * val * (1.0f + erff(val * k));

        output[idx] = val;
    }
}

torch::Tensor fused_bias_div_gelu_hip(torch::Tensor input, torch::Tensor bias, float divisor) {
    auto output = torch::empty_like(input);
    int rows = input.size(0);
    int cols = input.size(1);
    int total_elements = rows * cols;

    // Check alignment for float4 vectorization
    // input, bias, output pointers must be 16-byte aligned.
    // cols must be divisible by 4.
    bool aligned = (cols % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(input.data_ptr()) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(bias.data_ptr()) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(output.data_ptr()) % 16 == 0);

    if (aligned) {
        int total_vecs = total_elements / 4;
        const int block_size = 256;
        const int num_blocks = (total_vecs + block_size - 1) / block_size;

        fused_bias_div_gelu_vec_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            bias.data_ptr<float>(),
            output.data_ptr<float>(),
            divisor,
            cols,
            total_vecs
        );
    } else {
        const int block_size = 256;
        const int num_blocks = (total_elements + block_size - 1) / block_size;

        fused_bias_div_gelu_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            bias.data_ptr<float>(),
            output.data_ptr<float>(),
            divisor,
            cols,
            total_elements
        );
    }
    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    functions=["fused_bias_div_gelu_hip"],
    verbose=False,
    extra_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused_op = fused_ops

    def forward(self, x):
        # Performs: GELU((x @ W.T + b) / divisor)
        # 1. x @ W.T (Matrix Multiplication)
        y = torch.mm(x, self.linear.weight.t())

        # 2. Fused Add Bias + Divide + GELU
        return self.fused_op.fused_bias_div_gelu_hip(y, self.linear.bias, self.divisor)

