    batch_size = 1024
    input_size = 8192
    return [torch.rand(batch_size, input_size).cuda()]

def get_init_inputs():
    input_size = 8192
    output_size = 8192
    divisor = 10.0
    return [input_size, output_size, divisor]

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void group_norm_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int N, int C, int H, int W, int G, float eps) {

    // Grid: x=N, y=G
    // Block: 256 threads

    int n = blockIdx.x;
    int g = blockIdx.y;

    int C_per_G = C / G;
    int num_elements = C_per_G * H * W;

    long long batch_offset = (long long)n * C * H * W;
    long long group_offset = (long long)g * C_per_G * H * W;
    const float* group_data = x + batch_offset + group_offset;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < num_elements; i += blockDim.x) {
        float val = group_data[i];
        sum += val;
        sum_sq += val * val;
    }

    // Block reduction
    __shared__ float s_sum[256];
    __shared__ float s_sum_sq[256];

    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mu = s_sum[0] / num_elements;
        float var = (s_sum_sq[0] / num_elements) - (mu * mu);
        if (var < 0.0f) var = 0.0f;

        mean[n * G + g] = mu;
        rstd[n * G + g] = rsqrtf(var + eps);
    }
}

__global__ void fused_apply_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N, int C, int H_in, int W_in, int G,
    int H_out, int W_out,
    int pool_k,
    float clamp_min, float clamp_max) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * C * H_out * W_out;

    if (idx >= total_threads) return;

    // Decode idx -> (n, c, oh, ow)
    int temp = idx;
    int ow = temp % W_out;
    temp /= W_out;
    int oh = temp % H_out;
    temp /= H_out;
    int c = temp % C;
    int n = temp / C;

    int C_per_G = C / G;
    int g = c / C_per_G;

    float mu = mean[n * G + g];
    float rs = rstd[n * G + g];

    float gamma = gn_weight[c];
    float beta = gn_bias[c];
    float s = scale[c];

    int h_start = oh * pool_k;
    int w_start = ow * pool_k;

    float max_val = -3.402823466e+38F; // -FLT_MAX

    long long input_offset = (long long)n * C * H_in * W_in + (long long)c * H_in * W_in;
    const float* ch_input = x + input_offset;

    for (int i = 0; i < pool_k; ++i) {
        for (int j = 0; j < pool_k; ++j) {
            int h_in = h_start + i;
            int w_in = w_start + j;

            float val = ch_input[h_in * W_in + w_in];

            float norm = (val - mu) * rs;
            float gn_out = norm * gamma + beta;
            float scaled = gn_out * s;

            if (scaled > max_val) {
                max_val = scaled;
            }
        }
    }

    if (max_val < clamp_min) max_val = clamp_min;
    if (max_val > clamp_max) max_val = clamp_max;

    out[idx] = max_val;
}

torch::Tensor fused_forward(torch::Tensor x, torch::Tensor gn_weight, torch::Tensor gn_bias, torch::Tensor scale, 
                            int num_groups, int pool_k, float clamp_min, float clamp_max, float eps) {

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto mean = torch::empty({N, num_groups}, x.options());
    auto rstd = torch::empty({N, num_groups}, x.options());

    dim3 stats_grid(N, num_groups);
    dim3 stats_block(256);

    group_norm_stats_kernel<<<stats_grid, stats_block>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        N, C, H, W, num_groups, eps
    );

    int H_out = H / pool_k;
    int W_out = W / pool_k;

    auto out = torch::empty({N, C, H_out, W_out}, x.options());

    int total_elements = N * C * H_out * W_out;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    fused_apply_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        gn_weight.data_ptr<float>(),
        gn_bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, num_groups,
        H_out, W_out,
        pool_k,
        clamp_min, clamp_max
    );

    return out;
}
"""

fused_op = load_inline(
    name="fused_gn_pool",
    cpp_sources=cpp_source,
    functions=["fused_forward"],
    extra_cflags=["-O3"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.fused_op = fused_op

    def forward(self, x):
        x = self.conv(x)
        return self.fused_op.fused_forward(
            x, 
            self.group_norm.weight, 
            self.group_norm.bias, 
            self.scale,
            self.group_norm.num_groups,
            self.maxpool_kernel_size,
            self.clamp_min,
            self.clamp_max,
            self.group_norm.eps
        )

