cpp_source = """
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cmath>

__device__ __forceinline__ float rand_uniform(unsigned int idx, unsigned int seed) {
    unsigned int h = idx ^ seed;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return (float)h / 4294967296.0f;
}

__global__ void fused_dropout_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int rows,
    int cols,
    float p,
    float scale,
    unsigned int seed
) {
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int stride = blockDim.x;

    const float* row_in = input + row * cols;
    float* row_out = output + row * cols;

    // Local stats
    float local_max = -1e30f;
    float local_sum = 0.0f;

    // Pass 1: Compute Max and Sum (Online update)
    // We compute stats over the "dropout-ed" values
    for (int i = tid; i < cols; i += stride) {
        float val = row_in[i];

        // Apply dropout logic locally
        if (p > 0.0f) {
            unsigned int global_idx = row * cols + i;
            float r = rand_uniform(global_idx, seed);
            if (r < p) {
                val = 0.0f; // Drop
            } else {
                val *= scale; // Keep and Scale
            }
        }

        // Online Max/Sum update
        if (val > local_max) {
            float diff = local_max - val; // negative
            local_sum = local_sum * expf(diff) + 1.0f;
            local_max = val;
        } else {
            local_sum += expf(val - local_max);
        }
    }

    // Block Reduction: Max
    __shared__ float s_max[1024];
    s_max[tid] = local_max;
    __syncthreads();

    for (int s = stride / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (s_max[tid + s] > s_max[tid]) {
                s_max[tid] = s_max[tid + s];
            }
        }
        __syncthreads();
    }
    float global_max = s_max[0];

    // Adjust local sum to global max
    local_sum = local_sum * expf(local_max - global_max);

    // Block Reduction: Sum
    __shared__ float s_sum[1024];
    s_sum[tid] = local_sum;
    __syncthreads();

    for (int s = stride / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
        }
        __syncthreads();
    }
    float global_sum = s_sum[0];

    // Pass 2: Write Output
    for (int i = tid; i < cols; i += stride) {
        float val = row_in[i];

        // Re-compute dropout to get the same value
        if (p > 0.0f) {
            unsigned int global_idx = row * cols + i;
            float r = rand_uniform(global_idx, seed);
            if (r < p) {
                val = 0.0f;
            } else {
                val *= scale;
            }
        }

        // Softmax normalization
        row_out[i] = expf(val - global_max) / global_sum;
    }
}

torch::Tensor fused_dropout_softmax_hip(torch::Tensor input, double p, double scale, int64_t seed) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);

    int block_size = 1024;
    int grid_size = rows;

    fused_dropout_softmax_kernel<<<grid_size, block_size, 0, at::cuda::getCurrentCUDAStream()>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols,
        (float)p,
        (float)scale,
        (unsigned int)seed
    );

    return output;
}
"""

