#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_swish_scale_kernel(const float* __restrict__ inp, float* __restrict__ out, float scale, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized load/store using float4
    int vec_size = size / 4;
    const float4* inp_vec = reinterpret_cast<const float4*>(inp);
    float4* out_vec = reinterpret_cast<float4*>(out);

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = inp_vec[i];
        float4 r;

        // Swish = x * sigmoid(x) = x / (1 + exp(-x))
        r.x = v.x * (1.0f / (1.0f + expf(-v.x))) * scale;
        r.y = v.y * (1.0f / (1.0f + expf(-v.y))) * scale;
        r.z = v.z * (1.0f / (1.0f + expf(-v.z))) * scale;
        r.w = v.w * (1.0f / (1.0f + expf(-v.w))) * scale;

        out_vec[i] = r;
    }

    // Remainder loop
    int rem_start = vec_size * 4;
    for (int i = rem_start + idx; i < size; i += stride) {
        float v = inp[i];
        out[i] = v * (1.0f / (1.0f + expf(-v))) * scale;
    }
}

