    auto out = torch::empty_like(x);
    int size = x.numel();

    const int block_size = 256;
    // Calculate grid size based on vectorized size
    int vec_size = size / 4;
    int num_blocks = std::min(65535, (vec_size + block_size - 1) / block_size);
    if (num_blocks == 0) num_blocks = 1;

    fused_swish_scale_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), scale, size);

    return out;
}
