#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int N,
    const int C,
    const int H_in,
    const int W_in,
    const int H_out,
    const int W_out,
    const int pool_k,
    const float sub1,
    const float sub2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        // Output layout: N, C, H_out, W_out
        int w_out = idx % W_out;
        int tmp = idx / W_out;
        int h_out = tmp % H_out;
        tmp = tmp / H_out;
        int c = tmp % C;
        int n = tmp / C;

        float sum = 0.0f;

        int h_start = h_out * pool_k;
        int w_start = w_out * pool_k;

        // Base offset for this channel/batch
        int input_base = n * (C * H_in * W_in) + c * (H_in * W_in);

        // Unroll loops manually for 2x2 case or let compiler handle small loops
        // Given pool_k is likely small, a simple loop is fine.
        for (int i = 0; i < pool_k; ++i) {
            for (int j = 0; j < pool_k; ++j) {
                int h_in = h_start + i;
                int w_in = w_start + j;

                int input_idx = input_base + h_in * W_in + w_in;
                float val = input[input_idx];

                // Operations: x - sub1, then tanh, then - sub2
                val = tanhf(val - sub1) - sub2;

                sum += val;
            }
        }

        // Average pooling
        // We assume valid windows here as per typical AvgPool behavior with these dims
        float count = (float)(pool_k * pool_k);
        output[idx] = sum / count;
    }
}

