cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_instance_norm_divide_kernel(
    float* __restrict__ data,
    int HW,
    float divide_by,
    float epsilon) 
{
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int nc = blockIdx.x; 

    // Offset for this instance
    size_t offset = (size_t)nc * HW;
    float* img = data + offset;

    // --- Pass 1: Sum ---
    float local_sum = 0.0f;
    for (int i = tid; i < HW; i += blockDim.x) {
        local_sum += img[i];
    }

    sdata[tid] = local_sum;
    __syncthreads();

    // Reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / HW;

    __shared__ float sh_mean;
    if (tid == 0) sh_mean = mean;
    __syncthreads();
    mean = sh_mean;

    // --- Pass 2: Sum of Squared Differences ---
    float local_sq_diff = 0.0f;
    for (int i = tid; i < HW; i += blockDim.x) {
        float diff = img[i] - mean;
        local_sq_diff += diff * diff;
    }

    sdata[tid] = local_sq_diff;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // --- Pass 3: Normalize & Divide ---
    __shared__ float sh_scale;
    if (tid == 0) {
        float var = sdata[0] / HW;
        sh_scale = rsqrtf(var + epsilon) / divide_by;
    }
    __syncthreads();
    float scale = sh_scale;

    for (int i = tid; i < HW; i += blockDim.x) {
        img[i] = (img[i] - mean) * scale;
    }
}

torch::Tensor fused_instance_norm_divide_hip(torch::Tensor input, float divide_by) {
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int HW = H * W;

    int num_instances = N * C;
    int block_size = 256;
    size_t shared_mem_size = block_size * sizeof(float);

    fused_instance_norm_divide_kernel<<<num_instances, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        HW,
        divide_by,
        1e-5f
    );

    return input;
}
"""

