#include <hip/hip_runtime.h>
#include <cmath>
#include <torch/extension.h>

__global__ void fused_gelu_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int rows,
    int cols
) {
    // Shared memory layout:
    // [0 ... cols-1]: row data (values)
    // [cols ... cols+blockDim.x-1]: reduction buffer
    extern __shared__ float shared_mem[];
    float* row_data = shared_mem;
    float* sdata = &row_data[cols];

    int tid = threadIdx.x;
    int row_idx = blockIdx.x;

    if (row_idx >= rows) return;

    int row_offset = row_idx * cols;
    const float SQRT_2_INV = 0.70710678f;
    float local_max = -INFINITY;

    // Vectorized Handling using float4
    // cols must be divisible by 4
    int vec_cols = cols / 4;
    const float4* input_vec = reinterpret_cast<const float4*>(input + row_offset);
    float4* row_data_vec = reinterpret_cast<float4*>(row_data);

    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 in_val = input_vec[i];
        float4 out_val;

        // Process 4 elements
        // x
        float v = in_val.x;
        v = 0.5f * v * (1.0f + erff(v * SQRT_2_INV));
        out_val.x = v;
        local_max = fmaxf(local_max, v);

        // y
        v = in_val.y;
        v = 0.5f * v * (1.0f + erff(v * SQRT_2_INV));
        out_val.y = v;
        local_max = fmaxf(local_max, v);

        // z
        v = in_val.z;
        v = 0.5f * v * (1.0f + erff(v * SQRT_2_INV));
        out_val.z = v;
        local_max = fmaxf(local_max, v);

        // w
        v = in_val.w;
        v = 0.5f * v * (1.0f + erff(v * SQRT_2_INV));
        out_val.w = v;
        local_max = fmaxf(local_max, v);

        row_data_vec[i] = out_val;
    }

    // Block Reduce Max
    sdata[tid] = local_max;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    float row_max_val = sdata[0];

    // Compute Exp and Sum
    float local_sum = 0.0f;
    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 val = row_data_vec[i];

        val.x = expf(val.x - row_max_val);
        local_sum += val.x;

        val.y = expf(val.y - row_max_val);
        local_sum += val.y;

        val.z = expf(val.z - row_max_val);
        local_sum += val.z;

        val.w = expf(val.w - row_max_val);
        local_sum += val.w;

        row_data_vec[i] = val;
    }

    // Block Reduce Sum
    sdata[tid] = local_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    float row_sum_val = sdata[0];

    // Normalize and Write
    float inv_sum = 1.0f / row_sum_val;
    float4* output_vec = reinterpret_cast<float4*>(output + row_offset);

    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 val = row_data_vec[i];
        val.x *= inv_sum;
        val.y *= inv_sum;
        val.z *= inv_sum;
        val.w *= inv_sum;
        output_vec[i] = val;
    }
}

torch::Tensor fused_gelu_softmax_hip(torch::Tensor input) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int grid_size = rows;

    // Shared memory: cols floats + block_size floats
    int shared_mem_size = (cols + block_size) * sizeof(float);

    fused_gelu_softmax_kernel<<<grid_size, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols
    );

    return output;
}
