#include <hip/hip_runtime.h>
#include <cmath>
#include <cstdint>

__global__ void __launch_bounds__(256) fused_bias_div_gelu_vec_inplace_kernel(
    float* __restrict__ in_out,
    const float* __restrict__ bias,
    float divisor,
    int cols,
    int total_vecs
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_vecs) {
        float4* io_vec = reinterpret_cast<float4*>(in_out);
        const float4* b_vec = reinterpret_cast<const float4*>(bias);

        float4 v = io_vec[idx];

        int vec_cols = cols >> 2;
        int col_idx = idx % vec_cols;
        float4 b = b_vec[col_idx];

        float inv_div = 1.0f / divisor;
        float k = 0.707106781f; // 1/sqrt(2)

        v.x = (v.x + b.x) * inv_div;
        v.x = 0.5f * v.x * (1.0f + erff(v.x * k));

        v.y = (v.y + b.y) * inv_div;
        v.y = 0.5f * v.y * (1.0f + erff(v.y * k));

        v.z = (v.z + b.z) * inv_div;
        v.z = 0.5f * v.z * (1.0f + erff(v.z * k));

        v.w = (v.w + b.w) * inv_div;
        v.w = 0.5f * v.w * (1.0f + erff(v.w * k));

        io_vec[idx] = v;
    }
}

__global__ void fused_bias_div_gelu_inplace_kernel(
    float* __restrict__ in_out,
    const float* __restrict__ bias,
    float divisor,
    int cols,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int col = idx % cols;
        float val = in_out[idx];
        float b = bias[col];

        val = (val + b) / divisor;

        float k = 0.707106781f;
        val = 0.5f * val * (1.0f + erff(val * k));

        in_out[idx] = val;
    }
}

void fused_bias_div_gelu_hip_inplace(torch::Tensor input, torch::Tensor bias, float divisor) {
    int rows = input.size(0);
    int cols = input.size(1);
    int total_elements = rows * cols;

    // Check alignment for float4 vectorization
    bool aligned = (cols % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(input.data_ptr()) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(bias.data_ptr()) % 16 == 0);

    if (aligned) {
        int total_vecs = total_elements / 4;
        const int block_size = 256;
        const int num_blocks = (total_vecs + block_size - 1) / block_size;

        fused_bias_div_gelu_vec_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            bias.data_ptr<float>(),
            divisor,
            cols,
            total_vecs
        );
    } else {
        const int block_size = 256;
        const int num_blocks = (total_elements + block_size - 1) / block_size;

        fused_bias_div_gelu_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            bias.data_ptr<float>(),
            divisor,
            cols,
            total_elements
        );
    }
}
