#include <hip/hip_runtime.h>
#include <cmath>
#include <cstdint>

__global__ void __launch_bounds__(256) fused_div_gelu_vec_inplace_kernel(
    float* __restrict__ in_out,
    float divisor,
    int total_vecs
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_vecs) {
        float4* io_vec = reinterpret_cast<float4*>(in_out);
        float4 v = io_vec[idx];

        float inv_div = 1.0f / divisor;
        float k = 0.707106781f; // 1/sqrt(2)

        v.x *= inv_div;
        v.x = 0.5f * v.x * (1.0f + erff(v.x * k));

        v.y *= inv_div;
        v.y = 0.5f * v.y * (1.0f + erff(v.y * k));

        v.z *= inv_div;
        v.z = 0.5f * v.z * (1.0f + erff(v.z * k));

        v.w *= inv_div;
        v.w = 0.5f * v.w * (1.0f + erff(v.w * k));

        io_vec[idx] = v;
    }
}

__global__ void fused_div_gelu_inplace_kernel(
    float* __restrict__ in_out,
    float divisor,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float val = in_out[idx];

        val /= divisor;

        float k = 0.707106781f;
        val = 0.5f * val * (1.0f + erff(val * k));

        in_out[idx] = val;
    }
}

void fused_div_gelu_hip_inplace(torch::Tensor input, float divisor) {
    int rows = input.size(0);
    int cols = input.size(1);
    int total_elements = rows * cols;

    // Check alignment for float4 vectorization
    bool aligned = (cols % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(input.data_ptr()) % 16 == 0);

    if (aligned) {
        int total_vecs = total_elements / 4;
        const int block_size = 256;
        const int num_blocks = (total_vecs + block_size - 1) / block_size;

        fused_div_gelu_vec_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            divisor,
            total_vecs
        );
    } else {
        const int block_size = 256;
        const int num_blocks = (total_elements + block_size - 1) / block_size;

        fused_div_gelu_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            divisor,
            total_elements
        );
    }
}
"""

fused_ops = load_inline(
