cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void group_norm_stats_kernel_float4(
    const float* __restrict__ x,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int N, int C, int H, int W, int G, float eps) {

    int n = blockIdx.x;
    int g = blockIdx.y;

    int C_per_G = C / G;
    int num_elements = C_per_G * H * W;
    int num_vectors = num_elements / 4;

    long long batch_offset = (long long)n * C * H * W;
    long long group_offset = (long long)g * C_per_G * H * W;
    const float4* group_data = (const float4*)(x + batch_offset + group_offset);

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < num_vectors; i += blockDim.x) {
        float4 v = group_data[i];
        sum += v.x + v.y + v.z + v.w;
        sum_sq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    }

    int processed = num_vectors * 4;
    const float* raw_data = x + batch_offset + group_offset;
    for (int i = processed + threadIdx.x; i < num_elements; i += blockDim.x) {
         float val = raw_data[i];
         sum += val;
         sum_sq += val * val;
    }

    __shared__ float s_sum[256];
    __shared__ float s_sum_sq[256];

    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mu = s_sum[0] / num_elements;
        float var = (s_sum_sq[0] / num_elements) - (mu * mu);
        if (var < 0.0f) var = 0.0f;

        mean[n * G + g] = mu;
        rstd[n * G + g] = rsqrtf(var + eps);
    }
}

__global__ void fused_apply_kernel_shared_k4(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N, int C, int H_in, int W_in, int G,
    int H_out, int W_out,
    float clamp_min, float clamp_max) {

    extern __shared__ float smem[];

    int n = blockIdx.z;
    int c = blockIdx.y;
    int h_chunk = blockIdx.x;

    int h_out_start = h_chunk * 8;
    int h_out_end = min(h_out_start + 8, H_out);
    int num_h_out = h_out_end - h_out_start;

    if (num_h_out <= 0) return;

    int h_in_start = h_out_start * 4;
    int num_rows_to_load = 32; 
    int total_floats = num_rows_to_load * W_in;

    long long batch_c_offset = (long long)n * C * H_in * W_in + (long long)c * H_in * W_in;

    for (int i = threadIdx.x; i < total_floats; i += blockDim.x) {
        int row = i / W_in;
        int col = i % W_in;
        int global_row = h_in_start + row;

        if (global_row < H_in) {
            smem[i] = x[batch_c_offset + global_row * W_in + col];
        }
    }

    __syncthreads();

    int C_per_G = C / G;
    int g = c / C_per_G;
    float mu = mean[n * G + g];
    float rs = rstd[n * G + g];
    float gamma = gn_weight[c];
    float beta = gn_bias[c];
    float s = scale[c];

    int total_pixels = num_h_out * W_out;

    for (int i = threadIdx.x; i < total_pixels; i += blockDim.x) {
        int local_oh = i / W_out;
        int ow = i % W_out;
        int oh = h_out_start + local_oh;

        int smem_row_start = local_oh * 4;
        int smem_col_start = ow * 4;

        float max_val = -3.402823466e+38F;

        #pragma unroll
        for (int wy = 0; wy < 4; ++wy) {
            #pragma unroll
            for (int wx = 0; wx < 4; ++wx) {
                float val = smem[(smem_row_start + wy) * W_in + (smem_col_start + wx)];
                float norm = (val - mu) * rs;
                float gn_out = norm * gamma + beta;
                float scaled = gn_out * s;
                if (scaled > max_val) max_val = scaled;
            }
        }

        if (max_val < clamp_min) max_val = clamp_min;
        if (max_val > clamp_max) max_val = clamp_max;

        long long out_idx = (long long)n * C * H_out * W_out + (long long)c * H_out * W_out + (long long)oh * W_out + ow;
        out[out_idx] = max_val;
    }
}

torch::Tensor fused_forward(torch::Tensor x, torch::Tensor gn_weight, torch::Tensor gn_bias, torch::Tensor scale, 
                            int num_groups, int pool_k, float clamp_min, float clamp_max, float eps) {

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto mean = torch::empty({N, num_groups}, x.options());
    auto rstd = torch::empty({N, num_groups}, x.options());

    dim3 stats_grid(N, num_groups);
    dim3 stats_block(256);

    group_norm_stats_kernel_float4<<<stats_grid, stats_block>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        N, C, H, W, num_groups, eps
    );

    int H_out = H / pool_k;
    int W_out = W / pool_k;

    auto out = torch::empty({N, C, H_out, W_out}, x.options());

    if (pool_k == 4) {
        dim3 grid((H_out + 7) / 8, C, N);
        int block_size = 256;
        int smem_size = 32 * W * sizeof(float);

        fused_apply_kernel_shared_k4<<<grid, block_size, smem_size>>>(
            x.data_ptr<float>(),
            mean.data_ptr<float>(),
            rstd.data_ptr<float>(),
            gn_weight.data_ptr<float>(),
            gn_bias.data_ptr<float>(),
            scale.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C, H, W, num_groups,
            H_out, W_out,
            clamp_min, clamp_max
        );
    }

    return out;
}
"""

