cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>

// float4 is built-in

__device__ __forceinline__ float rand_uniform(unsigned int idx, unsigned int seed) {
    unsigned int h = idx ^ seed;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return (float)h / 4294967296.0f;
}

__device__ __forceinline__ float warpReduceMax(float val) {
    int ws = warpSize; 
    for (int offset = ws / 2; offset > 0; offset /= 2)
        val = max(val, __shfl_down(val, offset));
    return val;
}

__device__ __forceinline__ float warpReduceSum(float val) {
    int ws = warpSize;
    for (int offset = ws / 2; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

__global__ void fused_dropout_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int rows,
    int cols,
    float p,
    float scale,
    unsigned int seed
) {
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;
    int ws = warpSize;
    int lane = tid % ws;
    int warp_id = tid / ws;
    int num_warps = blockDim.x / ws;

    __shared__ float s_max[64]; 
    __shared__ float s_sum[64];

    const float* row_in = input + row * cols;
    float* row_out = output + row * cols;

    // Vectorized loads
    int vec_cols = cols / 4;

    const float4* row_in_vec = reinterpret_cast<const float4*>(row_in);
    float4* row_out_vec = reinterpret_cast<float4*>(row_out);

    float local_max = -1e30f;
    float local_sum = 0.0f;

    // Pass 1: Max and Sum
    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 v = row_in_vec[i];
        float vals[4] = {v.x, v.y, v.z, v.w};

        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            float val = vals[k];
            if (p > 0.0f) {
                unsigned int global_idx = row * cols + (i * 4 + k);
                float r = rand_uniform(global_idx, seed);
                if (r < p) val = 0.0f;
                else val *= scale;
            }

            if (val > local_max) {
                float diff = local_max - val;
                local_sum = local_sum * expf(diff) + 1.0f;
                local_max = val;
            } else {
                local_sum += expf(val - local_max);
            }
        }
    }

    float warp_max = warpReduceMax(local_max);
    if (lane == 0) s_max[warp_id] = warp_max;
    __syncthreads();

    float global_max;
    if (tid == 0) {
        float m = -1e30f;
        for (int i=0; i<num_warps; ++i) m = max(m, s_max[i]);
        s_max[0] = m;
    }
    __syncthreads();
    global_max = s_max[0];

    local_sum = local_sum * expf(local_max - global_max);
    float warp_sum = warpReduceSum(local_sum);
    if (lane == 0) s_sum[warp_id] = warp_sum;
    __syncthreads();

    float global_sum;
    if (tid == 0) {
        float s = 0.0f;
        for (int i=0; i<num_warps; ++i) s += s_sum[i];
        s_sum[0] = s;
    }
    __syncthreads();
    global_sum = s_sum[0];

    // Pass 2: Write
    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 v = row_in_vec[i];
        float vals[4] = {v.x, v.y, v.z, v.w};
        float4 out_v;

        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            float val = vals[k];
            if (p > 0.0f) {
                unsigned int global_idx = row * cols + (i * 4 + k);
                float r = rand_uniform(global_idx, seed);
                if (r < p) val = 0.0f;
                else val *= scale;
            }
            vals[k] = expf(val - global_max) / global_sum;
        }
        out_v.x = vals[0]; out_v.y = vals[1]; out_v.z = vals[2]; out_v.w = vals[3];
        row_out_vec[i] = out_v;
    }
}

torch::Tensor fused_dropout_softmax_hip(torch::Tensor input, double p, double scale, int64_t seed, int64_t stream_ptr) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);

    int block_size = 1024;
    int grid_size = rows;

    hipStream_t stream = reinterpret_cast<hipStream_t>(stream_ptr);

    fused_dropout_softmax_kernel<<<grid_size, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols,
        (float)p,
        (float)scale,
        (unsigned int)seed
    );

    return output;
}
"""

fused_ops = load_inline(
