        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor

        # Optimization: Fold division into weights and bias
        # (X @ W.T + b) / div = X @ (W.T / div) + (b / div)
        with torch.no_grad():
