            float m = workspace_max[row * chunks_per_row + c];
            float s = workspace_sum[row * chunks_per_row + c];
            g_sum += s * expf(m - g_max);
        }
        s_global_sum = g_sum;
    }
    __syncthreads();

    float global_max = s_global_max;
    float global_sum = s_global_sum;

    int chunk_size = cols / chunks_per_row;
    int start_col = chunk * chunk_size;
    const float* row_in = input + row * cols;
    float* row_out = output + row * cols;

    const float4* row_in_vec = reinterpret_cast<const float4*>(row_in);
    float4* row_out_vec = reinterpret_cast<float4*>(row_out);

    int vec_start = start_col / 4;
    int vec_end = vec_start + (chunk_size / 4);

    for (int i = vec_start + tid; i < vec_end; i += blockDim.x) {
        float4 v = row_in_vec[i];
        float vals[4] = {v.x, v.y, v.z, v.w};
        float4 out_v;
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            float val = vals[k];
            if (p > 0.0f) {
                unsigned int global_idx = row * cols + (i * 4 + k);
                float r = rand_uniform(global_idx, seed);
                if (r < p) val = 0.0f; else val *= scale;
            }
            vals[k] = expf(val - global_max) / global_sum;
        }
        out_v.x = vals[0]; out_v.y = vals[1]; out_v.z = vals[2]; out_v.w = vals[3];
        row_out_vec[i] = out_v;
    }
}

torch::Tensor fused_dropout_softmax_split(torch::Tensor input, double p, double scale, int64_t seed, int64_t stream_ptr) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);
    int chunks_per_row = 16;

    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(input.device());
    auto workspace_max = torch::empty({rows, chunks_per_row}, options);
    auto workspace_sum = torch::empty({rows, chunks_per_row}, options);

    hipStream_t stream = reinterpret_cast<hipStream_t>(stream_ptr);

    dim3 grid(rows, chunks_per_row);
    int block_size = 256;

    reduce_step1_kernel<<<grid, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        workspace_max.data_ptr<float>(),
        workspace_sum.data_ptr<float>(),
        rows, cols, chunks_per_row,
        (float)p, (float)scale, (unsigned int)seed
    );

    reduce_step2_kernel<<<grid, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        workspace_max.data_ptr<float>(),
        workspace_sum.data_ptr<float>(),
        rows, cols, chunks_per_row,
        (float)p, (float)scale, (unsigned int)seed
    );

    return output;
}
"""

fused_ops = load_inline(
    name="fused_dropout_softmax_v5",
    cpp_sources=cpp_source,
    functions=["fused_dropout_softmax_split"],
    extra_include_paths=[],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, dropout_p):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.dropout_p = dropout_p
        self.fused_op = fused_ops

    def forward(self, x):
        x = self.matmul(x)
        if self.training and self.dropout_p > 0.0:
            p = self.dropout_p
            scale = 1.0 / (1.0 - p)
            seed = torch.cuda.initial_seed() & 0xFFFFFFFF
        else:
            p = 0.0
            scale = 1.0
            seed = 0
        stream = torch.cuda.current_stream().cuda_stream
        return self.fused_op.fused_dropout_softmax_split(x, p, scale, seed, stream)

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

# Ensure HIP compiler is used
os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <cmath>
#include <cstdint>

__device__ __forceinline__ float gelu_tanh(float x) {
    const float k0 = 0.79788456f; 
    const float k1 = 0.044715f;
    float x3 = x * x * x;
    return 0.5f * x * (1.0f + tanhf(k0 * (x + k1 * x3)));
}

__global__ void __launch_bounds__(256) gelu_vec_inplace_kernel(
    float* __restrict__ in_out,
    int total_vecs
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_vecs) {
        float4* io_vec = reinterpret_cast<float4*>(in_out);
        float4 v = io_vec[idx];

        v.x = gelu_tanh(v.x);
        v.y = gelu_tanh(v.y);
        v.z = gelu_tanh(v.z);
        v.w = gelu_tanh(v.w);

        io_vec[idx] = v;
    }
}

__global__ void gelu_inplace_kernel(
    float* __restrict__ in_out,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        in_out[idx] = gelu_tanh(in_out[idx]);
    }
}

void gelu_hip_inplace(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);
    int total_elements = rows * cols;

    bool aligned = (cols % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(input.data_ptr()) % 16 == 0);

    if (aligned) {
        int total_vecs = total_elements / 4;
        const int block_size = 256;
        const int num_blocks = (total_vecs + block_size - 1) / block_size;

        gelu_vec_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            total_vecs
        );
    } else {
        const int block_size = 256;
        const int num_blocks = (total_elements + block_size - 1) / block_size;

        gelu_inplace_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            total_elements
        );
    }
}
"""

gelu_op = load_inline(
    name="gelu_op_tanh",
    cpp_sources=cpp_source,
    functions=["gelu_hip_inplace"],
    verbose=False,
    extra_cflags=['-O3', '-ffast-math']
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor

        # Optimization 1: Fold division into weights and bias
        with torch.no_grad():
            self.linear.weight.div_(divisor)
            self.linear.bias.div_(divisor)

        self.gelu_op = gelu_op
        self.graphed_forward = None

    def _forward_impl(self, x):
        # Optimization 2: Linear + In-place Custom GELU
        y = self.linear(x)
        self.gelu_op.gelu_hip_inplace(y)
        return y

    def forward(self, x):
        # Optimization 3: CUDA Graph
        if self.graphed_forward is None:
             self.graphed_forward = torch.cuda.make_graphed_callables(
                 self._forward_impl, (x,)
             )

        return self.graphed_forward(x)

